/**
 * Movable, splittable course workspace built on dockview. It moves the existing course index, course content and
 * blocks nodes into dockview panels (the nodes are moved, never cloned, so Moodle's own scripts keep working) and
 * puts them back when the workspace is switched off or the window becomes narrow.
 *
 * @module     theme_material/workspace
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('theme_material/workspace', ['core/ajax', 'theme_material/vendor-dockview'], function(Ajax, Dockview) {
    var MIN_WIDTH = 1200;
    var MAX_LAYOUT = 20000;
    var SAVE_DELAY = 800;
    var PREF_MODE = 'theme_material_workspace';
    var PREF_LAYOUT = 'theme_material_workspace_layout';
    var COLOURS = ['primary', 'secondary', 'tertiary', 'error', 'success'];
    var SEARCH_PATH = 'M15.5 14h-.79l-.28-.27A6.47 6.47 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 ' +
        '4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z';
    var CLOSE_PATH = 'M19 6.41 17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z';

    // The three panels and where their existing nodes live in the page.
    var DEFS = [
        {key: 'index', find: function() {
            return document.querySelector('#theme_boost-drawers-courseindex .drawercontent');
        }},
        {key: 'course', find: function() {
            return document.getElementById('region-main-box');
        }},
        {key: 'blocks', find: function() {
            var node = document.querySelector('#theme_boost-drawers-blocks .drawercontent');
            return node && node.querySelector('[data-block], .block') ? node : null;
        }}
    ];

    var config = null;
    var strings = {};
    var ws = null;
    var classicBar = null;
    var saveTimer = null;
    var lastSaved = '';
    var counter = 0;

    /**
     * Look up a language string, replacing the %s placeholder when a value is given.
     *
     * @param {string} key
     * @param {string} [value]
     * @returns {string}
     */
    function str(key, value) {
        var text = strings[key] || '';
        return value === undefined ? text.replace('%s', '').trim() : text.replace('%s', value);
    }

    /**
     * Create an element with a class and optional text.
     *
     * @param {string} tag
     * @param {string} [cls]
     * @param {string} [text]
     * @returns {HTMLElement}
     */
    function el(tag, cls, text) {
        var node = document.createElement(tag);
        if (cls) {
            node.className = cls;
        }
        if (text !== undefined) {
            node.textContent = text;
        }
        return node;
    }

    /**
     * Build a small inline icon from one SVG path.
     *
     * @param {string} path
     * @returns {SVGElement}
     */
    function icon(path) {
        var ns = 'http://www.w3.org/2000/svg';
        var svg = document.createElementNS(ns, 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('width', '18');
        svg.setAttribute('height', '18');
        svg.setAttribute('aria-hidden', 'true');
        svg.setAttribute('focusable', 'false');
        var p = document.createElementNS(ns, 'path');
        p.setAttribute('fill', 'currentColor');
        p.setAttribute('d', path);
        svg.appendChild(p);
        return svg;
    }

    /**
     * Save one user preference. A failed save never interrupts the page.
     *
     * @param {string} name
     * @param {string} value
     */
    function savePref(name, value) {
        try {
            var calls = Ajax.call([{
                methodname: 'core_user_set_user_preferences',
                args: {preferences: [{name: name, value: value, userid: config.userid}]}
            }]);
            if (calls[0] && calls[0].catch) {
                calls[0].catch(function() {
                    return null;
                });
            }
        } catch (e) {
            return;
        }
    }

    /**
     * Is the keyboard focus in a field where typing must not be intercepted?
     *
     * @param {EventTarget} target
     * @returns {boolean}
     */
    function editable(target) {
        if (!target || !target.tagName) {
            return false;
        }
        var tag = target.tagName.toLowerCase();
        return tag === 'input' || tag === 'textarea' || tag === 'select' || target.isContentEditable === true;
    }

    /**
     * Announce a message to screen readers.
     *
     * @param {string} message
     */
    function announce(message) {
        if (!ws) {
            return;
        }
        ws.live.textContent = '';
        window.setTimeout(function() {
            if (ws) {
                ws.live.textContent = message;
            }
        }, 30);
    }

    // ------------------------------------------------------------------------------------------------ saving

    /**
     * Turn the current layout and the tab state into the saved string.
     *
     * @returns {string}
     */
    function serialize() {
        return JSON.stringify({v: 1, dock: ws.api.toJSON(), pinned: ws.pinned});
    }

    /**
     * Save the layout now when it changed.
     */
    function flush() {
        window.clearTimeout(saveTimer);
        if (!ws || !ws.ready) {
            return;
        }
        var value;
        try {
            value = serialize();
        } catch (e) {
            return;
        }
        if (value === lastSaved || value.length > MAX_LAYOUT) {
            return;
        }
        lastSaved = value;
        config.layout = value;
        savePref(PREF_LAYOUT, value);
    }

    /**
     * Save the layout shortly after the last change.
     */
    function scheduleSave() {
        if (!ws || !ws.ready) {
            return;
        }
        window.clearTimeout(saveTimer);
        saveTimer = window.setTimeout(flush, SAVE_DELAY);
    }

    // ------------------------------------------------------------------------------------------------ helpers

    /**
     * The tab part of a panel, when it is on screen.
     *
     * @param {string} id
     * @returns {object|null}
     */
    function tabFor(id) {
        for (var i = 0; i < ws.tabs.length; i++) {
            if (ws.tabs[i].id === id) {
                return ws.tabs[i];
            }
        }
        return null;
    }

    /**
     * Move keyboard focus to a panel's tab.
     *
     * @param {object} panel
     */
    function focusTab(panel) {
        var tab = panel ? tabFor(panel.id) : null;
        var wrapper = tab ? tab.element.closest('.dv-tab') : null;
        if (wrapper) {
            wrapper.focus();
        }
    }

    /**
     * Redraw every tab, after a pin or lock change.
     */
    function refreshTabs() {
        ws.tabs.forEach(function(tab) {
            tab.render();
        });
    }

    /**
     * Title of one of the three panels.
     *
     * @param {string} key
     * @returns {string}
     */
    function titleFor(key) {
        return str('workspacepanel' + key);
    }

    // ------------------------------------------------------------------------------------------------ actions

    /**
     * Pin or unpin a tab. Pinned tabs cannot be closed.
     *
     * @param {object} panel
     */
    function togglePin(panel) {
        if (ws.pinned[panel.id]) {
            delete ws.pinned[panel.id];
        } else {
            ws.pinned[panel.id] = true;
        }
        refreshTabs();
        scheduleSave();
    }

    /**
     * Lock or unlock a group. Nothing can be dropped into a locked group.
     *
     * @param {object} group
     */
    function toggleLock(group) {
        group.locked = group.locked ? false : 'no-drop-target';
        refreshTabs();
        scheduleSave();
    }

    /**
     * Close a tab unless it is pinned.
     *
     * @param {object} panel
     */
    function closeTab(panel) {
        if (ws.pinned[panel.id]) {
            announce(str('workspacepinnednoclose'));
            return;
        }
        var title = panel.title || titleFor(panel.id);
        panel.api.close();
        announce(str('workspaceclosed', title));
    }

    /**
     * Move a tab into a new group beside its current one.
     *
     * @param {object} panel
     */
    function moveToNewGroup(panel) {
        var group = panel.group;
        if (!group || group.panels.length < 2) {
            return;
        }
        var created = ws.api.addGroup({referenceGroup: group, direction: 'right'});
        panel.api.moveTo({group: created});
        panel.api.setActive();
        focusTab(panel);
    }

    /**
     * Put a tab into a new named tab group.
     *
     * @param {object} panel
     */
    function newTabGroup(panel) {
        var group = panel.group;
        var created = ws.api.createTabGroup({groupId: group.id, label: str('workspacegroupdefault'), color: COLOURS[0]});
        ws.api.addPanelToTabGroup({groupId: group.id, tabGroupId: created.id, panelId: panel.id});
    }

    /**
     * Open a closed panel again.
     *
     * @param {string} key
     */
    function reopen(key) {
        var options = {id: key, component: key, tabComponent: 'mm', title: titleFor(key)};
        var group = ws.api.activeGroup;
        if (group) {
            options.position = {referenceGroup: group, direction: 'within'};
        }
        var panel = ws.api.addPanel(options);
        panel.api.setActive();
        focusTab(panel);
        announce(str('workspacereopened', titleFor(key)));
    }

    /**
     * Build the default layout: course index left, course centre, blocks right.
     */
    function buildDefault() {
        ws.api.clear();
        ws.pinned = {};
        var side = Math.round((ws.dock.clientWidth || 1200) * 0.25);
        var common = {component: 'course', tabComponent: 'mm'};
        ws.api.addPanel({id: 'course', component: common.component, tabComponent: common.tabComponent, title: titleFor('course')});
        var sized = [];
        if (ws.entries.index) {
            sized.push(ws.api.addPanel({
                id: 'index', component: 'index', tabComponent: 'mm', title: titleFor('index'), initialWidth: side,
                position: {referencePanel: 'course', direction: 'left'}
            }));
        }
        if (ws.entries.blocks) {
            sized.push(ws.api.addPanel({
                id: 'blocks', component: 'blocks', tabComponent: 'mm', title: titleFor('blocks'), initialWidth: side,
                position: {referencePanel: 'course', direction: 'right'}
            }));
        }
        window.requestAnimationFrame(function() {
            sized.forEach(function(panel) {
                try {
                    panel.api.setSize({width: side});
                } catch (e) {
                    return;
                }
            });
        });
        var course = ws.api.getPanel('course');
        if (course) {
            course.api.setActive();
        }
    }

    /**
     * Is a saved layout safe to load?
     *
     * @param {object} blob
     * @returns {boolean}
     */
    function validBlob(blob) {
        if (!blob || blob.v !== 1 || !blob.dock || typeof blob.dock !== 'object' || !blob.dock.panels) {
            return false;
        }
        var ids = Object.keys(blob.dock.panels);
        if (!ids.length) {
            return false;
        }
        return ids.every(function(id) {
            return !!ws.entries[id];
        });
    }

    /**
     * Restore the saved layout, or fall back to the default layout on any problem.
     */
    function restore() {
        var blob = null;
        try {
            blob = config.layout ? JSON.parse(config.layout) : null;
        } catch (e) {
            blob = null;
        }
        if (validBlob(blob)) {
            try {
                ws.api.fromJSON(blob.dock);
                var pinned = {};
                Object.keys(blob.pinned || {}).forEach(function(id) {
                    if (ws.entries[id] && blob.pinned[id] === true) {
                        pinned[id] = true;
                    }
                });
                ws.pinned = pinned;
                if (ws.api.totalPanels > 0) {
                    return;
                }
            } catch (e) {
                // Fall through to the default layout.
            }
        }
        buildDefault();
    }

    /**
     * Throw away the saved arrangement and show the default one.
     */
    function resetLayout() {
        buildDefault();
        refreshTabs();
        flush();
        announce(str('workspacelayoutreset'));
    }

    // ------------------------------------------------------------------------------------------------ popovers

    /**
     * Close the open search or layout popover.
     *
     * @param {boolean} [restoreFocus]
     */
    function closePop(restoreFocus) {
        if (!ws || !ws.pop) {
            return;
        }
        var pop = ws.pop;
        ws.pop = null;
        document.removeEventListener('pointerdown', pop.outside, true);
        if (pop.node.parentNode) {
            pop.node.parentNode.removeChild(pop.node);
        }
        if (pop.anchor) {
            pop.anchor.setAttribute('aria-expanded', 'false');
            if (restoreFocus) {
                pop.anchor.focus();
            }
        }
    }

    /**
     * Show a popover under a button.
     *
     * @param {HTMLElement} anchor
     * @param {HTMLElement} node
     */
    function openPop(anchor, node) {
        closePop(false);
        ws.root.appendChild(node);
        var outside = function(event) {
            if (!node.contains(event.target) && !anchor.contains(event.target)) {
                closePop(false);
            }
        };
        document.addEventListener('pointerdown', outside, true);
        ws.pop = {node: node, anchor: anchor, outside: outside};
        anchor.setAttribute('aria-expanded', 'true');
        var rootBox = ws.root.getBoundingClientRect();
        var box = anchor.getBoundingClientRect();
        var left = Math.max(8, Math.min(box.left - rootBox.left, rootBox.width - node.offsetWidth - 8));
        node.style.top = (box.bottom - rootBox.top + 4) + 'px';
        node.style.left = left + 'px';
        node.addEventListener('keydown', function(event) {
            if (event.key === 'Escape') {
                event.preventDefault();
                closePop(true);
            }
        });
    }

    /**
     * Open the searchable list of every tab, open or closed.
     *
     * @param {HTMLElement} anchor
     */
    function openSearch(anchor) {
        if (ws.pop && ws.pop.anchor === anchor) {
            closePop(true);
            return;
        }
        var id = 'mm-ws-search-' + (++counter);
        var node = el('div', 'mm-ws-pop');
        var label = el('label', '', str('workspacesearchlabel'));
        label.setAttribute('for', id + '-q');
        var input = el('input');
        input.type = 'search';
        input.id = id + '-q';
        input.autocomplete = 'off';
        input.setAttribute('role', 'combobox');
        input.setAttribute('aria-controls', id + '-list');
        input.setAttribute('aria-expanded', 'true');
        // No aria-autocomplete: Boost's page-wide combobox key handler (document, capture phase) acts on
        // autocomplete comboboxes and expects its own option markup. This field handles its own keys.
        var list = el('ul', 'mm-ws-results');
        list.id = id + '-list';
        list.setAttribute('role', 'listbox');
        list.setAttribute('aria-label', str('workspacesearchtabs'));
        var status = el('p', 'mm-ws-note');
        status.setAttribute('role', 'status');
        node.appendChild(label);
        node.appendChild(input);
        node.appendChild(list);
        node.appendChild(status);

        var shown = [];
        var active = 0;
        var paint = function() {
            var needle = input.value.trim().toLocaleLowerCase();
            shown = DEFS.filter(function(def) {
                return ws.entries[def.key] && titleFor(def.key).toLocaleLowerCase().indexOf(needle) !== -1;
            }).map(function(def) {
                return {key: def.key, title: titleFor(def.key), open: !!ws.api.getPanel(def.key)};
            });
            active = Math.min(active, Math.max(shown.length - 1, 0));
            list.textContent = '';
            shown.forEach(function(item, index) {
                var row = el('li', 'mm-ws-result');
                row.id = id + '-opt-' + index;
                row.setAttribute('role', 'option');
                row.setAttribute('aria-selected', index === active ? 'true' : 'false');
                row.appendChild(el('span', '', item.title));
                row.appendChild(el('span', 'mm-ws-result-state', item.open ? str('workspacestateopen') :
                    str('workspacestateclosed')));
                row.addEventListener('click', function() {
                    choose(item);
                });
                list.appendChild(row);
            });
            if (shown.length) {
                input.setAttribute('aria-activedescendant', id + '-opt-' + active);
            } else {
                input.removeAttribute('aria-activedescendant');
            }
            status.textContent = shown.length ? str('workspacesearchcount', String(shown.length)) :
                str('workspacesearchnone');
        };
        var choose = function(item) {
            closePop(false);
            var panel = ws.api.getPanel(item.key);
            if (panel) {
                panel.api.setActive();
                focusTab(panel);
            } else {
                reopen(item.key);
            }
        };
        input.addEventListener('input', function() {
            active = 0;
            paint();
        });
        input.addEventListener('keydown', function(event) {
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                event.preventDefault();
                if (shown.length) {
                    active = (active + (event.key === 'ArrowDown' ? 1 : -1) + shown.length) % shown.length;
                    paint();
                }
            } else if (event.key === 'Enter') {
                event.preventDefault();
                if (shown[active]) {
                    choose(shown[active]);
                }
            }
        });
        paint();
        openPop(anchor, node);
        input.focus();
    }

    /**
     * Open the Layout menu.
     *
     * @param {HTMLElement} anchor
     */
    function openLayoutMenu(anchor) {
        if (ws.pop && ws.pop.anchor === anchor) {
            closePop(true);
            return;
        }
        var node = el('div', 'mm-ws-menu');
        node.setAttribute('role', 'menu');
        node.setAttribute('aria-label', str('workspacelayout'));
        var make = function(label, shortcut, action) {
            var item = el('button', 'mm-ws-menu-item');
            item.type = 'button';
            item.setAttribute('role', 'menuitem');
            item.appendChild(el('span', '', label));
            if (shortcut) {
                item.appendChild(el('span', 'mm-ws-kbd', shortcut));
            }
            item.addEventListener('click', function() {
                closePop(true);
                action();
            });
            node.appendChild(item);
        };
        make(str('workspaceresetlayout'), 'Ctrl+Alt+R', resetLayout);
        make(str('workspaceclassic'), '', function() {
            setMode('classic');
        });
        node.addEventListener('keydown', function(event) {
            var items = Array.prototype.slice.call(node.querySelectorAll('[role="menuitem"]'));
            var at = items.indexOf(document.activeElement);
            if (event.key === 'ArrowDown') {
                event.preventDefault();
                items[(at + 1) % items.length].focus();
            } else if (event.key === 'ArrowUp') {
                event.preventDefault();
                items[(at - 1 + items.length) % items.length].focus();
            }
        });
        openPop(anchor, node);
        node.querySelector('[role="menuitem"]').focus();
    }

    // ------------------------------------------------------------------------------------------------ tab menu

    /**
     * Close the tab context menu that dockview opened.
     *
     * @param {HTMLElement} item
     */
    function closeTabMenu(item) {
        var menu = item.closest('.dv-context-menu');
        if (menu && menu.parentNode) {
            menu.parentNode.remove();
        }
        // The library listens for a press outside its menu to release its own listeners.
        document.body.dispatchEvent(new window.PointerEvent('pointerdown', {bubbles: true}));
    }

    /**
     * One row of the tab menu: a label and its keyboard shortcut.
     *
     * @param {string} label
     * @param {string} shortcut
     * @param {Function} action
     * @param {boolean} [disabled]
     * @param {string} [swatch] CSS colour shown before the label
     * @param {boolean} [checked]
     * @returns {HTMLElement}
     */
    function menuRow(label, shortcut, action, disabled, swatch, checked) {
        var row = el('div', 'dv-context-menu-item');
        row.setAttribute('role', 'menuitem');
        row.tabIndex = -1;
        if (swatch) {
            var dot = el('span', 'mm-ws-swatch');
            dot.style.background = swatch;
            row.appendChild(dot);
        }
        row.appendChild(el('span', '', label));
        if (shortcut) {
            row.appendChild(el('span', 'mm-ws-kbd', shortcut));
        }
        if (checked) {
            row.appendChild(el('span', 'mm-ws-check', '✓'));
            row.setAttribute('aria-checked', 'true');
        }
        if (disabled) {
            row.setAttribute('aria-disabled', 'true');
            row.classList.add('dv-context-menu-item--disabled');
            return row;
        }
        var run = function() {
            closeTabMenu(row);
            action();
        };
        row.addEventListener('click', run);
        row.addEventListener('keydown', function(event) {
            var rows = Array.prototype.slice.call(row.parentNode.querySelectorAll('[role="menuitem"]:not([aria-disabled="true"])'));
            var at = rows.indexOf(row);
            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                run();
            } else if (event.key === 'ArrowDown') {
                event.preventDefault();
                rows[(at + 1) % rows.length].focus();
            } else if (event.key === 'ArrowUp') {
                event.preventDefault();
                rows[(at - 1 + rows.length) % rows.length].focus();
            } else if (event.key === 'Home') {
                event.preventDefault();
                rows[0].focus();
            } else if (event.key === 'End') {
                event.preventDefault();
                rows[rows.length - 1].focus();
            }
        });
        return row;
    }

    /**
     * A thin divider between menu sections.
     *
     * @returns {HTMLElement}
     */
    function menuRule() {
        var rule = el('div', 'dv-context-menu-separator');
        rule.setAttribute('role', 'separator');
        return rule;
    }

    /**
     * The rename field for a tab group.
     *
     * @param {object} tabGroup
     * @param {object} panel
     * @returns {HTMLElement}
     */
    function menuRename(tabGroup, panel) {
        var wrap = el('div', 'mm-ws-menu-field');
        var id = 'mm-ws-rename-' + (++counter);
        var label = el('label', '', str('workspacegroupname'));
        label.setAttribute('for', id);
        var input = el('input');
        input.type = 'text';
        input.id = id;
        input.value = tabGroup.label || '';
        input.maxLength = 40;
        input.addEventListener('keydown', function(event) {
            event.stopPropagation();
            if (event.key === 'Enter') {
                event.preventDefault();
                tabGroup.setLabel(input.value.trim());
                closeTabMenu(input);
                focusTab(panel);
            } else if (event.key === 'ArrowDown') {
                event.preventDefault();
                var rows = wrap.parentNode.querySelectorAll('[role="menuitem"]:not([aria-disabled="true"])');
                var next = Array.prototype.find.call(rows, function(row) {
                    return wrap.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_FOLLOWING;
                });
                if (next) {
                    next.focus();
                }
            }
        });
        input.addEventListener('blur', function() {
            if (input.value.trim() !== tabGroup.label && input.isConnected) {
                tabGroup.setLabel(input.value.trim());
            }
        });
        wrap.appendChild(label);
        wrap.appendChild(input);
        return wrap;
    }

    /**
     * Build the context menu rows for one tab.
     *
     * @param {object} params
     * @returns {object[]}
     */
    function tabMenuItems(params) {
        var panel = params.panel;
        var group = params.group;
        var pinned = !!ws.pinned[panel.id];
        var rows = [
            menuRow(str(pinned ? 'workspaceunpin' : 'workspacepin'), 'Ctrl+Alt+P', function() {
                togglePin(panel);
            }),
            menuRow(str(group.locked ? 'workspaceunlock' : 'workspacelock'), 'Ctrl+Alt+L', function() {
                toggleLock(group);
            }),
            menuRow(str('workspacemovenew'), 'Ctrl+Alt+N', function() {
                moveToNewGroup(panel);
            }, group.panels.length < 2),
            menuRow(str('workspaceclose'), 'Ctrl+Alt+W', function() {
                closeTab(panel);
            }, pinned),
            menuRule()
        ];
        var tabGroup = ws.api.getTabGroupForPanel({groupId: group.id, panelId: panel.id});
        if (tabGroup) {
            rows.push(menuRename(tabGroup, panel));
            COLOURS.forEach(function(colour) {
                rows.push(menuRow(str('workspacecolour' + colour), '', function() {
                    tabGroup.setColor(colour);
                }, false, 'var(--md-sys-color-' + colour + ')', tabGroup.color === colour));
            });
            rows.push(menuRow(str('workspaceremovegroup'), '', function() {
                ws.api.removePanelFromTabGroup({groupId: group.id, panelId: panel.id});
            }));
        } else {
            rows.push(menuRow(str('workspacetabgroup'), '', function() {
                newTabGroup(panel);
            }));
        }
        rows.push(menuRule());
        rows.push(menuRow(str('workspaceresetlayout'), 'Ctrl+Alt+R', resetLayout));
        window.setTimeout(function() {
            var first = rows[0];
            if (first && first.isConnected) {
                first.focus();
            }
        }, 60);
        return rows.map(function(row) {
            return {element: row};
        });
    }

    // ------------------------------------------------------------------------------------------------ renderers

    /**
     * Content renderer: holds one of the moved page nodes.
     *
     * @param {string} key
     * @constructor
     */
    function ContentPart(key) {
        this.key = key;
        this.element = el('div', 'mm-ws-panel');
        this.element.setAttribute('data-mm-panel', key);
    }
    ContentPart.prototype.init = function() {
        var entry = ws && ws.entries[this.key];
        if (entry) {
            this.element.appendChild(entry.node);
        }
    };
    ContentPart.prototype.dispose = function() {
        var entry = ws && ws.entries[this.key];
        if (entry && ws.holder) {
            ws.holder.appendChild(entry.node);
        }
    };

    /**
     * Tab renderer: the title, a pinned or locked badge and a Close button that carries a text label.
     *
     * @constructor
     */
    function TabPart() {
        this.element = el('div', 'mm-ws-tab');
        this.label = el('span', 'mm-ws-tab-label');
        this.state = el('span', 'mm-ws-tab-state');
        this.close = el('button', 'mm-ws-tab-close');
        this.close.type = 'button';
        this.close.appendChild(icon(CLOSE_PATH));
        this.closeText = el('span', '', str('workspaceclose'));
        this.close.appendChild(this.closeText);
        this.element.appendChild(this.label);
        this.element.appendChild(this.state);
        this.element.appendChild(this.close);
        this.title = '';
        this.id = '';
        this.api = null;
    }
    TabPart.prototype.init = function(params) {
        var self = this;
        this.api = params.api;
        this.id = params.api.id;
        this.title = params.title || titleFor(this.id);
        this.close.addEventListener('pointerdown', function(event) {
            event.preventDefault();
        });
        this.close.addEventListener('click', function(event) {
            event.preventDefault();
            event.stopPropagation();
            var panel = ws.api.getPanel(self.id);
            if (panel) {
                closeTab(panel);
            }
        });
        this.titleListener = params.api.onDidTitleChange(function(event) {
            self.title = event.title || self.title;
            self.render();
        });
        ws.tabs.push(this);
        this.render();
    };
    TabPart.prototype.render = function() {
        var pinned = !!(ws && ws.pinned[this.id]);
        var group = this.api ? this.api.group : null;
        var locked = !!(group && group.locked);
        this.label.textContent = this.title;
        var badges = [];
        if (pinned) {
            badges.push(str('workspacepinned'));
        }
        if (locked) {
            badges.push(str('workspacelocked'));
        }
        this.state.textContent = badges.join(', ');
        this.state.hidden = badges.length === 0;
        this.close.hidden = pinned;
        this.close.setAttribute('aria-label', str('workspaceclosetab', this.title));
    };
    TabPart.prototype.dispose = function() {
        if (this.titleListener && this.titleListener.dispose) {
            this.titleListener.dispose();
        }
        if (ws) {
            ws.tabs = ws.tabs.filter(function(tab) {
                return tab !== this;
            }, this);
        }
    };

    /**
     * Header action renderer: the Search tabs button each group carries.
     *
     * @constructor
     */
    function ActionsPart() {
        this.element = el('div', 'mm-ws-actions');
    }
    ActionsPart.prototype.init = function() {
        var button = el('button', 'mm-ws-btn mm-ws-icon-btn');
        button.type = 'button';
        button.title = str('workspacesearchtabs') + ' (Ctrl+Alt+F)';
        button.setAttribute('aria-haspopup', 'listbox');
        button.setAttribute('aria-expanded', 'false');
        button.appendChild(icon(SEARCH_PATH));
        button.appendChild(el('span', 'mm-ws-visually-hidden', str('workspacesearchtabs')));
        button.addEventListener('click', function() {
            openSearch(button);
        });
        this.element.appendChild(button);
    };
    ActionsPart.prototype.dispose = function() {
        this.element.textContent = '';
    };

    // ------------------------------------------------------------------------------------------------ keyboard

    /**
     * Show the next or previous tab in the active group.
     *
     * @param {number} step
     */
    function cycleTab(step) {
        var group = ws.api.activeGroup;
        if (!group || group.panels.length < 2) {
            return;
        }
        var panels = group.panels;
        var at = panels.indexOf(ws.api.activePanel);
        var next = panels[(at + step + panels.length) % panels.length];
        next.api.setActive();
        focusTab(next);
    }

    /**
     * Move focus to the neighbouring group.
     *
     * @param {string} direction left, right, up or down
     */
    function focusGroup(direction) {
        var current = ws.api.activeGroup;
        if (!current) {
            return;
        }
        var next = ws.api.adjacentGroupInDirection(current, direction);
        if (!next) {
            return;
        }
        next.api.setActive();
        focusTab(next.activePanel);
    }

    /**
     * Keyboard routes for the workspace.
     *
     * @param {KeyboardEvent} event
     */
    function onKey(event) {
        if (!ws || !ws.root.contains(document.activeElement) || editable(event.target)) {
            return;
        }
        var arrows = {ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down'};
        if (event.ctrlKey && !event.altKey && !event.metaKey && event.key === 'Tab') {
            event.preventDefault();
            cycleTab(event.shiftKey ? -1 : 1);
            return;
        }
        if (!event.ctrlKey || !event.altKey || event.metaKey) {
            return;
        }
        var panel = ws.api.activePanel;
        var handled = true;
        if (arrows[event.key]) {
            focusGroup(arrows[event.key]);
        } else if (event.key === 'PageDown' || event.key === 'PageUp') {
            cycleTab(event.key === 'PageDown' ? 1 : -1);
        } else if (event.code === 'KeyP' && panel) {
            togglePin(panel);
        } else if (event.code === 'KeyL' && panel) {
            toggleLock(panel.group);
        } else if (event.code === 'KeyN' && panel) {
            moveToNewGroup(panel);
        } else if (event.code === 'KeyW' && panel) {
            closeTab(panel);
        } else if (event.code === 'KeyR') {
            resetLayout();
        } else if (event.code === 'KeyF') {
            openSearch(ws.searchButton);
        } else {
            handled = false;
        }
        if (handled) {
            event.preventDefault();
        }
    }

    // ------------------------------------------------------------------------------------------------ lifecycle

    /**
     * Create the workspace, move the page nodes into it and load the layout.
     */
    function build() {
        var host = document.getElementById('page-content');
        var entries = {};
        DEFS.forEach(function(def) {
            var node = def.find();
            if (node) {
                entries[def.key] = {node: node, marker: null};
            }
        });
        if (!host || !entries.course) {
            return;
        }
        var root = el('div', 'mm-ws');
        root.id = 'mm-workspace';
        root.setAttribute('role', 'region');
        root.setAttribute('aria-label', str('workspacetitle'));
        var bar = el('div', 'mm-ws-bar');
        var title = el('h2', 'mm-ws-title', str('workspacetitle'));
        var help = el('span', 'mm-ws-visually-hidden', str('workspacehelp'));
        help.id = 'mm-ws-help';
        var searchButton = el('button', 'mm-ws-btn');
        searchButton.type = 'button';
        searchButton.setAttribute('aria-haspopup', 'listbox');
        searchButton.setAttribute('aria-expanded', 'false');
        searchButton.title = 'Ctrl+Alt+F';
        searchButton.appendChild(icon(SEARCH_PATH));
        searchButton.appendChild(el('span', '', str('workspacesearchtabs')));
        var layoutButton = el('button', 'mm-ws-btn', str('workspacelayout'));
        layoutButton.type = 'button';
        layoutButton.setAttribute('aria-haspopup', 'menu');
        layoutButton.setAttribute('aria-expanded', 'false');
        layoutButton.setAttribute('aria-describedby', 'mm-ws-help');
        bar.appendChild(title);
        bar.appendChild(searchButton);
        bar.appendChild(layoutButton);
        bar.appendChild(help);
        var dock = el('div', 'mm-ws-dock');
        var holder = el('div', 'mm-ws-holder');
        var live = el('div', 'mm-ws-visually-hidden');
        live.setAttribute('role', 'status');
        root.appendChild(bar);
        root.appendChild(dock);
        root.appendChild(holder);
        root.appendChild(live);
        host.insertBefore(root, host.firstChild);

        Object.keys(entries).forEach(function(key) {
            var node = entries[key].node;
            entries[key].marker = document.createComment('mm-workspace:' + key);
            node.parentNode.insertBefore(entries[key].marker, node);
            holder.appendChild(node);
        });
        document.body.classList.add('mm-workspace-on');

        ws = {
            root: root, dock: dock, holder: holder, live: live, entries: entries, tabs: [], pinned: {},
            pop: null, api: null, ready: false, searchButton: searchButton, subs: []
        };
        searchButton.addEventListener('click', function() {
            openSearch(searchButton);
        });
        layoutButton.addEventListener('click', function() {
            openLayoutMenu(layoutButton);
        });

        ws.api = Dockview.createDockview(dock, {
            theme: {name: 'material', className: 'dockview-theme-material'},
            defaultRenderer: 'always',
            disableFloatingGroups: true,
            closeEmptyGroups: true,
            defaultTabComponent: 'mm',
            tabGroupColors: COLOURS.map(function(colour) {
                return {id: colour, value: 'var(--md-sys-color-' + colour + ')', label: str('workspacecolour' + colour)};
            }),
            createComponent: function(options) {
                if (!ws || !ws.entries[options.name]) {
                    throw new Error('Unknown workspace panel ' + options.name);
                }
                return new ContentPart(options.name);
            },
            createTabComponent: function() {
                return new TabPart();
            },
            createRightHeaderActionComponent: function() {
                return new ActionsPart();
            },
            getTabContextMenuItems: tabMenuItems
        });
        var watch = function(event) {
            if (event) {
                ws.subs.push(event(scheduleSave));
            }
        };
        watch(ws.api.onDidLayoutChange);
        watch(ws.api.onDidActivePanelChange);
        watch(ws.api.onDidAddPanel);
        watch(ws.api.onDidRemovePanel);
        watch(ws.api.onDidTabGroupChange);
        watch(ws.api.onDidCreateTabGroup);
        watch(ws.api.onDidDestroyTabGroup);
        watch(ws.api.onDidAddPanelToTabGroup);
        watch(ws.api.onDidRemovePanelFromTabGroup);

        restore();
        refreshTabs();
        lastSaved = serialize();
        ws.ready = true;
    }

    /**
     * Remove the workspace and put every moved node back where the page had it.
     */
    function teardown() {
        if (!ws) {
            return;
        }
        var old = ws;
        window.clearTimeout(saveTimer);
        closePop(false);
        old.ready = false;
        old.subs.forEach(function(sub) {
            if (sub && sub.dispose) {
                sub.dispose();
            }
        });
        try {
            old.api.dispose();
        } catch (e) {
            // The nodes are restored below whatever state the library is in.
        }
        Object.keys(old.entries).forEach(function(key) {
            var entry = old.entries[key];
            if (entry.marker && entry.marker.parentNode) {
                entry.marker.parentNode.replaceChild(entry.node, entry.marker);
            }
        });
        if (old.root.parentNode) {
            old.root.parentNode.removeChild(old.root);
        }
        document.body.classList.remove('mm-workspace-on');
        ws = null;
    }

    /**
     * Show the small bar that brings the workspace back while the classic layout is chosen.
     */
    function showClassicBar() {
        var host = document.getElementById('page-content');
        if (classicBar || !host) {
            return;
        }
        classicBar = el('div', 'mm-ws-classic-bar');
        var button = el('button', 'mm-ws-btn', str('workspaceuse'));
        button.type = 'button';
        button.addEventListener('click', function() {
            setMode('workspace');
        });
        classicBar.appendChild(button);
        host.insertBefore(classicBar, host.firstChild);
    }

    /**
     * Remove the classic layout bar.
     */
    function hideClassicBar() {
        if (classicBar && classicBar.parentNode) {
            classicBar.parentNode.removeChild(classicBar);
        }
        classicBar = null;
    }

    /**
     * Build or remove the workspace to match the preference and the window width.
     */
    function apply() {
        var wide = window.matchMedia('(min-width: ' + MIN_WIDTH + 'px)').matches;
        if (!wide) {
            teardown();
            hideClassicBar();
            return;
        }
        if (config.mode === 'classic') {
            teardown();
            showClassicBar();
        } else {
            hideClassicBar();
            if (!ws) {
                build();
            }
        }
    }

    /**
     * Switch between the workspace and the classic layout and remember the choice.
     *
     * @param {string} mode workspace or classic
     */
    function setMode(mode) {
        config.mode = mode;
        savePref(PREF_MODE, mode);
        apply();
    }

    return {
        /**
         * Start the workspace on a course page.
         *
         * @param {object} settings userid, mode, layout and strings
         */
        init: function(settings) {
            if (config) {
                return;
            }
            config = settings || {};
            strings = config.strings || {};
            var query = window.matchMedia('(min-width: ' + MIN_WIDTH + 'px)');
            if (query.addEventListener) {
                query.addEventListener('change', apply);
            } else if (query.addListener) {
                query.addListener(apply);
            }
            document.addEventListener('keydown', onKey);
            window.addEventListener('pagehide', flush);
            apply();
        }
    };
});
